let ended = now_ms();
self.db
.lock()
.unwrap()
.execute(
"UPDATE sessions SET status='closed', ended=?2 WHERE id=?1",
params![s.id, ended],
)
.map_err(storage_error)?;
Ok(json!({"session": s.id, "status": "closed", "ended": ended}))
}
